from collections import Counter

class Solution:
    def generatePalindromes(self, s: str) -> list[str]:
        counts = Counter(s)
        odd = [c for c in counts if counts[c] % 2]
        if len(odd) > 1:
            return []
        middle = ''.join(odd)
        for c in counts:
            counts[c] //= 2
        result, path = [], []
        def build():
            if len(path) == len(s) // 2:
                half = ''.join(path)
                result.append(half + middle + half[::-1])
                return
            for c in counts:
                if counts[c]:
                    counts[c] -= 1
                    path.append(c)
                    build()
                    path.pop()
                    counts[c] += 1
        build()
        return result
